// Everything below is DERIVED from the 228-item pool above by counting real examples —
// not guessed. Effect archetype is assigned by classifyEffect() below: run it over
// realMagicItems yourself and you'll reproduce categoryWeightsByRarity/archetypeWeightsByRarity/
// attunementRateByRarity exactly. It's a best-effort keyword read of real text, not a perfect
// taxonomy — "Utility/Other" is the catch-all for anything that doesn't match a
// Spell-like/Stat-set/Resistance-Immunity/Passive-bonus pattern below.
export function classifyEffect(effect: string): string {
  if (/\bcasts?\b.{0,50}\bfrom it\b|\byou can cast\b|casts one of the following spells|can cast the|can cast one of/i.test(effect))
    return "Spell-like";
  if (/score is \d|score becomes \d|Your \w+ is \d+ while/i.test(effect)) return "Stat-set";
  if (/Resistance to|Immunity to/i.test(effect)) return "Resistance/Immunity";
  if (/\+\d+ bonus to (Armor Class|saving throws|attack rolls|Armor Class and saving throws|ability checks)/i.test(effect))
    return "Passive bonus";
  return "Utility/Other";
}

